pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        // deploy a helper that does not revert so the transfer call succeeds in both versions
        Helper helper = new Helper();
        vm.prank(from);
        c.transfer(from, address(helper), _tos, v);
        assertTrue(true);
    }
}

contract Helper {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
